#!/usr/bin/env node
'use strict';

/**
 * Slack Web API caller for agents.
 *
 * POSTs JSON to https://slack.com/api/<method> and prints a compact result.
 * Requires Node.js 18+ (global fetch).
 *
 * Usage:
 *   node slack.cjs <method> [jsonArgs] [--pages N] [--full]
 *
 * Examples:
 *   node slack.cjs api.test
 *   node slack.cjs auth.test
 *   node slack.cjs chat.postMessage '{"channel":"C0123456789","text":"Hello"}'
 *   node slack.cjs conversations.history '{"channel":"C0123456789","limit":10}'
 *   node slack.cjs conversations.list '{"types":"public_channel"}' --pages 5
 *
 * Environment:
 *   SLACK_BOT_TOKEN       Bot token (xoxb-...). Recommended.
 *   SLACK_TOKEN           User token (xoxp-...) fallback.
 *   SLACK_OAUTH_TOKEN     Additional fallback.
 *   SLACK_API_BASE_URL    Override API base URL (default https://slack.com/api).
 */

const DEFAULT_BASE_URL = 'https://slack.com/api';
const DEFAULT_PAGES = 1;
const MAX_PAGES = 20;
const MAX_PRINT_LINES = 400;
const NO_TOKEN_METHODS = new Set(['api.test']);

function pickToken() {
  return (
    process.env.SLACK_BOT_TOKEN ||
    process.env.SLACK_TOKEN ||
    process.env.SLACK_OAUTH_TOKEN ||
    ''
  );
}

function helpText() {
  return [
    'Usage: node slack.cjs <method> [jsonArgs] [options]',
    '',
    'POSTs JSON to https://slack.com/api/<method> and prints a compact result.',
    '',
    'Arguments:',
    '  method       Slack Web API method, e.g. chat.postMessage',
    '  jsonArgs     JSON object of method parameters (must be quoted as one argument)',
    '',
    'Options:',
    '  --pages <n>  Follow response_metadata.next_cursor for up to n requests total (default ' + DEFAULT_PAGES + ')',
    '  --full       Print the entire response (default output is truncated at ' + MAX_PRINT_LINES + ' lines)',
    '  -h, --help   Show this help',
    '',
    'Examples:',
    '  node slack.cjs api.test',
    '  node slack.cjs auth.test',
    '  node slack.cjs chat.postMessage \'{"channel":"C0123456789","text":"Hello"}\'',
    '  node slack.cjs conversations.history \'{"channel":"C0123456789","limit":10}\'',
    '  node slack.cjs conversations.list \'{"types":"public_channel"}\' --pages 5',
    '',
    'Environment: set SLACK_BOT_TOKEN (xoxb-...) or SLACK_TOKEN (xoxp-...).',
    '',
  ].join('\n');
}

function parseArgs(argv) {
  const out = { method: null, args: {}, pages: DEFAULT_PAGES, full: false, help: false };
  const positional = [];
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      out.help = true;
    } else if (arg === '--full') {
      out.full = true;
    } else if (arg === '--pages') {
      const n = Number(argv[i + 1]);
      if (!Number.isInteger(n) || n < 1) {
        throw new Error('--pages requires a positive integer');
      }
      out.pages = n;
      i += 1;
    } else if (arg.startsWith('--')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      positional.push(arg);
    }
  }
  out.method = positional[0] || null;
  if (positional.length > 1) {
    const raw = positional.slice(1).join(' ');
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      throw new Error('JSON arguments do not parse: ' + raw.slice(0, 80));
    }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new Error('JSON arguments must be an object');
    }
    out.args = parsed;
  }
  return out;
}

class SlackApiError extends Error {
  constructor(body) {
    const detail = [];
    if (body.needed) detail.push('needed scope: ' + body.needed);
    if (body.provided) detail.push('provided scopes: ' + body.provided);
    if (body.errors && typeof body.errors === 'object') {
      detail.push('field errors: ' + JSON.stringify(body.errors));
    }
    const suffix = detail.length ? ' (' + detail.join('; ') + ')' : '';
    super('Slack API error: ' + (body.error || 'unknown') + suffix);
    this.name = 'SlackApiError';
    this.body = body;
  }
}

async function readJson(res) {
  if (res.status === 429) {
    let wait = '';
    if (res.headers && typeof res.headers.get === 'function') {
      wait = res.headers.get('retry-after') || '';
    }
    throw new Error('Slack rate limit (HTTP 429): wait ' + (wait || 'a few') + ' seconds and retry');
  }
  try {
    return await res.json();
  } catch (err) {
    throw new Error('HTTP ' + res.status + ' ' + res.statusText + ': response was not JSON');
  }
}

function mergeInto(target, body) {
  for (const key of Object.keys(body)) {
    if (key === 'ok' || key === 'response_metadata') continue;
    const value = body[key];
    if (Array.isArray(value)) {
      target[key] = (target[key] || []).concat(value);
    } else {
      target[key] = value;
    }
  }
}

/**
 * Call one Slack Web API method, following response_metadata.next_cursor
 * up to `pages` total requests (merging array results across pages).
 */
async function call(method, args = {}, opts = {}) {
  const token = opts.token !== undefined ? opts.token : pickToken();
  const baseUrl = opts.baseUrl || process.env.SLACK_API_BASE_URL || DEFAULT_BASE_URL;
  const maxPages = Math.min(Math.max(opts.pages || DEFAULT_PAGES, 1), MAX_PAGES);
  if (typeof fetch !== 'function') {
    throw new Error('global fetch is unavailable; run with Node.js 18+');
  }
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers.Authorization = 'Bearer ' + token;

  const merged = {};
  let pagesUsed = 0;
  let nextCursor = '';
  for (;;) {
    pagesUsed += 1;
    const payload = Object.assign({}, args);
    if (pagesUsed > 1 && nextCursor) payload.cursor = nextCursor;
    const res = await fetch(baseUrl + '/' + method, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
    });
    const body = await readJson(res);
    if (!body.ok) throw new SlackApiError(body);
    mergeInto(merged, body);
    nextCursor =
      body.response_metadata && body.response_metadata.next_cursor
        ? body.response_metadata.next_cursor
        : '';
    if (pagesUsed >= maxPages || !nextCursor) break;
  }
  if (nextCursor) merged.response_metadata = { next_cursor: nextCursor };
  return { ok: true, method, pagesUsed, hasMore: Boolean(nextCursor), response: merged };
}

function formatResponse(result, opts = {}) {
  const compact = {
    ok: result.ok,
    method: result.method,
    pagesUsed: result.pagesUsed,
    hasMore: result.hasMore,
    response: result.response,
  };
  const text = JSON.stringify(compact, null, 2);
  if (opts.full) return text;
  const lines = text.split('\n');
  if (lines.length <= MAX_PRINT_LINES) return text;
  return (
    lines.slice(0, MAX_PRINT_LINES).join('\n') +
    '\n... output truncated (' + lines.length + ' total lines); rerun with --full to print everything'
  );
}

async function runCli(argv, io = {}) {
  const out = io.out || ((s) => process.stdout.write(s));
  const err = io.err || ((s) => process.stderr.write(s));
  let parsed;
  try {
    parsed = parseArgs(argv);
  } catch (e) {
    err('Failure: ' + e.message + '\n');
    return 2;
  }
  if (parsed.help || !parsed.method) {
    out(helpText());
    return parsed.help ? 0 : 2;
  }
  try {
    const token = pickToken();
    if (!token && !NO_TOKEN_METHODS.has(parsed.method)) {
      err('Failure: no Slack token found. Set SLACK_BOT_TOKEN (xoxb-...) or SLACK_TOKEN (xoxp-...).\n');
      return 2;
    }
    const result = await call(parsed.method, parsed.args, { token, pages: parsed.pages });
    const text = formatResponse(result, { full: parsed.full });
    out(text.endsWith('\n') ? text : text + '\n');
    return 0;
  } catch (e) {
    err('Failure: ' + e.message + '\n');
    return 1;
  }
}

module.exports = { call, parseArgs, runCli, formatResponse, pickToken, SlackApiError, helpText };

if (require.main === module) {
  runCli(process.argv.slice(2)).then((code) => {
    process.exitCode = code;
  });
}

#!/usr/bin/env node
'use strict';

/**
 * Upload a local file to a Slack conversation using the current upload flow:
 *   1. files.getUploadURLExternal   -> upload_url and file_id
 *   2. PUT the raw file bytes to upload_url
 *   3. files.completeUploadExternal -> share the file into a channel
 *
 * Usage:
 *   node upload_file.cjs <file-path> [channel-id] [options]
 *
 * Options:
 *   --comment text    Initial comment shown with the file
 *   --thread-ts TS    Share the file as a reply inside that thread
 *   --title NAME      Display name (defaults to the file's basename)
 *   --alt-text TEXT   Accessibility description
 *   -h, --help        Show this help
 *
 * Environment:
 *   SLACK_BOT_TOKEN    Bot token (xoxb-...). Recommended.
 *   SLACK_TOKEN        User token (xoxp-...) fallback.
 *   SLACK_API_BASE_URL Override API base URL (default https://slack.com/api).
 */

const fs = require('node:fs');
const path = require('node:path');

const DEFAULT_BASE_URL = 'https://slack.com/api';

function pickToken() {
  return (
    process.env.SLACK_BOT_TOKEN ||
    process.env.SLACK_TOKEN ||
    process.env.SLACK_OAUTH_TOKEN ||
    ''
  );
}

function helpText() {
  return [
    'Usage: node upload_file.cjs <file-path> [channel-id] [options]',
    '',
    'Uploads a local file and shares it into a Slack channel using',
    'files.getUploadURLExternal + PUT + files.completeUploadExternal.',
    '',
    'Options:',
    '  --comment text   Initial comment shown with the file',
    '  --thread-ts TS   Share the file inside that thread',
    '  --title NAME     Display name (defaults to the file basename)',
    '  --alt-text TEXT  Accessibility description',
    '  -h, --help       Show this help',
    '',
    'Environment: set SLACK_BOT_TOKEN (xoxb-...) or SLACK_TOKEN (xoxp-...).',
    '',
  ].join('\n');
}

function parseArgs(argv) {
  const out = {
    file: null,
    channel: null,
    comment: null,
    threadTs: null,
    title: null,
    altText: null,
    help: false,
  };
  const positional = [];
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      out.help = true;
    } else if (arg === '--comment') {
      out.comment = argv[++i] || '';
    } else if (arg === '--thread-ts') {
      out.threadTs = argv[++i] || '';
    } else if (arg === '--title') {
      out.title = argv[++i] || '';
    } else if (arg === '--alt-text') {
      out.altText = argv[++i] || '';
    } else if (arg.startsWith('--')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      positional.push(arg);
    }
  }
  out.file = positional[0] || null;
  out.channel = positional[1] || null;
  return out;
}

class SlackApiError extends Error {
  constructor(body) {
    const detail = [];
    if (body.needed) detail.push('needed scope: ' + body.needed);
    if (body.provided) detail.push('provided scopes: ' + body.provided);
    const suffix = detail.length ? ' (' + detail.join('; ') + ')' : '';
    super('Slack API error: ' + (body.error || 'unknown') + suffix);
    this.name = 'SlackApiError';
    this.body = body;
  }
}

async function postJson(baseUrl, method, payload, token) {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers.Authorization = 'Bearer ' + token;
  const res = await fetch(baseUrl + '/' + method, {
    method: 'POST',
    headers,
    body: JSON.stringify(payload),
  });
  let body;
  try {
    body = await res.json();
  } catch (err) {
    throw new Error('HTTP ' + res.status + ' ' + res.statusText + ': response was not JSON');
  }
  if (!body.ok) throw new SlackApiError(body);
  return body;
}

async function runCli(argv, io = {}) {
  const out = io.out || ((s) => process.stdout.write(s));
  const err = io.err || ((s) => process.stderr.write(s));
  let parsed;
  try {
    parsed = parseArgs(argv);
  } catch (e) {
    err('Failure: ' + e.message + '\n');
    return 2;
  }
  if (parsed.help || !parsed.file) {
    out(helpText());
    return parsed.help ? 0 : 2;
  }
  try {
    if (typeof fetch !== 'function') {
      throw new Error('global fetch is unavailable; run with Node.js 18+');
    }
    const token = pickToken();
    if (!token) {
      err('Failure: no Slack token found. Set SLACK_BOT_TOKEN (xoxb-...) or SLACK_TOKEN (xoxp-...).\n');
      return 2;
    }
    const baseUrl = process.env.SLACK_API_BASE_URL || DEFAULT_BASE_URL;
    const filePath = path.resolve(parsed.file);
    if (!fs.existsSync(filePath)) throw new Error('file not found: ' + filePath);
    const stat = fs.statSync(filePath);
    if (!stat.isFile()) throw new Error('not a regular file: ' + filePath);

    const filename = parsed.title || path.basename(filePath);
    const initPayload = { filename, length: stat.size };
    if (parsed.altText) initPayload.alt_txt = parsed.altText;

    const init = await postJson(baseUrl, 'files.getUploadURLExternal', initPayload, token);
    const uploadUrl = init.upload_url;
    const fileId = init.file_id;
    if (!uploadUrl || !fileId) {
      throw new Error('upload response missing upload_url or file_id');
    }

    const data = fs.readFileSync(filePath);
    const putRes = await fetch(uploadUrl, {
      method: 'PUT',
      headers: {
        Authorization: 'Bearer ' + token,
        'Content-Type': 'application/octet-stream',
      },
      body: data,
    });
    if (!putRes.ok) {
      let detail = '';
      try {
        detail = (await putRes.text()).slice(0, 200);
      } catch (ignored) {
        /* no body */
      }
      throw new Error('upload PUT failed with HTTP ' + putRes.status + (detail ? ': ' + detail : ''));
    }

    const completePayload = { files: [{ id: fileId }] };
    if (parsed.channel) completePayload.channel_id = parsed.channel;
    if (parsed.comment) completePayload.initial_comment = parsed.comment;
    if (parsed.threadTs) completePayload.thread_ts = parsed.threadTs;
    const complete = await postJson(baseUrl, 'files.completeUploadExternal', completePayload, token);

    const result = {
      ok: true,
      file: filename,
      file_id: fileId,
      channel: complete.channel || parsed.channel || null,
      ts: complete.ts || (complete.files && complete.files[0] && complete.files[0].ts) || null,
      message: (complete.message && complete.message.text) || null,
    };
    out(JSON.stringify(result, null, 2) + '\n');
    return 0;
  } catch (e) {
    err('Failure: ' + e.message + '\n');
    return 1;
  }
}

module.exports = { parseArgs, runCli, pickToken, SlackApiError, helpText };

if (require.main === module) {
  runCli(process.argv.slice(2)).then((code) => {
    process.exitCode = code;
  });
}

