#!/usr/bin/env node
'use strict';

/**
 * Slack Web API caller for agents.
 *
 * POSTs JSON to https://slack.com/api/<method> and prints a compact result.
 * Requires Node.js 18+ (global fetch).
 *
 * Usage:
 *   node slack.cjs <method> [jsonArgs] [--pages N] [--full]
 *
 * Examples:
 *   node slack.cjs api.test
 *   node slack.cjs auth.test
 *   node slack.cjs chat.postMessage '{"channel":"C0123456789","text":"Hello"}'
 *   node slack.cjs conversations.history '{"channel":"C0123456789","limit":10}'
 *   node slack.cjs conversations.list '{"types":"public_channel"}' --pages 5
 *
 * Environment:
 *   SLACK_BOT_TOKEN       Bot token (xoxb-...). Recommended.
 *   SLACK_TOKEN           User token (xoxp-...) fallback.
 *   SLACK_OAUTH_TOKEN     Additional fallback.
 *   SLACK_API_BASE_URL    Override API base URL (default https://slack.com/api).
 */

const DEFAULT_BASE_URL = 'https://slack.com/api';
const DEFAULT_PAGES = 1;
const MAX_PAGES = 20;
const MAX_PRINT_LINES = 400;
const NO_TOKEN_METHODS = new Set(['api.test']);

function pickToken() {
  return (
    process.env.SLACK_BOT_TOKEN ||
    process.env.SLACK_TOKEN ||
    process.env.SLACK_OAUTH_TOKEN ||
    ''
  );
}

function helpText() {
  return [
    'Usage: node slack.cjs <method> [jsonArgs] [options]',
    '',
    'POSTs JSON to https://slack.com/api/<method> and prints a compact result.',
    '',
    'Arguments:',
    '  method       Slack Web API method, e.g. chat.postMessage',
    '  jsonArgs     JSON object of method parameters (must be quoted as one argument)',
    '',
    'Options:',
    '  --pages <n>  Follow response_metadata.next_cursor for up to n requests total (default ' + DEFAULT_PAGES + ')',
    '  --full       Print the entire response (default output is truncated at ' + MAX_PRINT_LINES + ' lines)',
    '  -h, --help   Show this help',
    '',
    'Examples:',
    '  node slack.cjs api.test',
    '  node slack.cjs auth.test',
    '  node slack.cjs chat.postMessage \'{"channel":"C0123456789","text":"Hello"}\'',
    '  node slack.cjs conversations.history \'{"channel":"C0123456789","limit":10}\'',
    '  node slack.cjs conversations.list \'{"types":"public_channel"}\' --pages 5',
    '',
    'Environment: set SLACK_BOT_TOKEN (xoxb-...) or SLACK_TOKEN (xoxp-...).',
    '',
  ].join('\n');
}

function parseArgs(argv) {
  const out = { method: null, args: {}, pages: DEFAULT_PAGES, full: false, help: false };
  const positional = [];
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      out.help = true;
    } else if (arg === '--full') {
      out.full = true;
    } else if (arg === '--pages') {
      const n = Number(argv[i + 1]);
      if (!Number.isInteger(n) || n < 1) {
        throw new Error('--pages requires a positive integer');
      }
      out.pages = n;
      i += 1;
    } else if (arg.startsWith('--')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      positional.push(arg);
    }
  }
  out.method = positional[0] || null;
  if (positional.length > 1) {
    const raw = positional.slice(1).join(' ');
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      throw new Error('JSON arguments do not parse: ' + raw.slice(0, 80));
    }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new Error('JSON arguments must be an object');
    }
    out.args = parsed;
  }
  return out;
}

class SlackApiError extends Error {
  constructor(body) {
    const detail = [];
    if (body.needed) detail.push('needed scope: ' + body.needed);
    if (body.provided) detail.push('provided scopes: ' + body.provided);
    if (body.errors && typeof body.errors === 'object') {
      detail.push('field errors: ' + JSON.stringify(body.errors));
    }
    const suffix = detail.length ? ' (' + detail.join('; ') + ')' : '';
    super('Slack API error: ' + (body.error || 'unknown') + suffix);
    this.name = 'SlackApiError';
    this.body = body;
  }
}

async function readJson(res) {
  if (res.status === 429) {
    let wait = '';
    if (res.headers && typeof res.headers.get === 'function') {
      wait = res.headers.get('retry-after') || '';
    }
    throw new Error('Slack rate limit (HTTP 429): wait ' + (wait || 'a few') + ' seconds and retry');
  }
  try {
    return await res.json();
  } catch (err) {
    throw new Error('HTTP ' + res.status + ' ' + res.statusText + ': response was not JSON');
  }
}

function mergeInto(target, body) {
  for (const key of Object.keys(body)) {
    if (key === 'ok' || key === 'response_metadata') continue;
    const value = body[key];
    if (Array.isArray(value)) {
      target[key] = (target[key] || []).concat(value);
    } else {
      target[key] = value;
    }
  }
}

/**
 * Call one Slack Web API method, following response_metadata.next_cursor
 * up to `pages` total requests (merging array results across pages).
 */
async function call(method, args = {}, opts = {}) {
  const token = opts.token !== undefined ? opts.token : pickToken();
  const baseUrl = opts.baseUrl || process.env.SLACK_API_BASE_URL || DEFAULT_BASE_URL;
  const maxPages = Math.min(Math.max(opts.pages || DEFAULT_PAGES, 1), MAX_PAGES);
  if (typeof fetch !== 'function') {
    throw new Error('global fetch is unavailable; run with Node.js 18+');
  }
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers.Authorization = 'Bearer ' + token;

  const merged = {};
  let pagesUsed = 0;
  let nextCursor = '';
  for (;;) {
    pagesUsed += 1;
    const payload = Object.assign({}, args);
    if (pagesUsed > 1 && nextCursor) payload.cursor = nextCursor;
    const res = await fetch(baseUrl + '/' + method, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
    });
    const body = await readJson(res);
    if (!body.ok) throw new SlackApiError(body);
    mergeInto(merged, body);
    nextCursor =
      body.response_metadata && body.response_metadata.next_cursor
        ? body.response_metadata.next_cursor
        : '';
    if (pagesUsed >= maxPages || !nextCursor) break;
  }
  if (nextCursor) merged.response_metadata = { next_cursor: nextCursor };
  return { ok: true, method, pagesUsed, hasMore: Boolean(nextCursor), response: merged };
}

function formatResponse(result, opts = {}) {
  const compact = {
    ok: result.ok,
    method: result.method,
    pagesUsed: result.pagesUsed,
    hasMore: result.hasMore,
    response: result.response,
  };
  const text = JSON.stringify(compact, null, 2);
  if (opts.full) return text;
  const lines = text.split('\n');
  if (lines.length <= MAX_PRINT_LINES) return text;
  return (
    lines.slice(0, MAX_PRINT_LINES).join('\n') +
    '\n... output truncated (' + lines.length + ' total lines); rerun with --full to print everything'
  );
}

async function runCli(argv, io = {}) {
  const out = io.out || ((s) => process.stdout.write(s));
  const err = io.err || ((s) => process.stderr.write(s));
  let parsed;
  try {
    parsed = parseArgs(argv);
  } catch (e) {
    err('Failure: ' + e.message + '\n');
    return 2;
  }
  if (parsed.help || !parsed.method) {
    out(helpText());
    return parsed.help ? 0 : 2;
  }
  try {
    const token = pickToken();
    if (!token && !NO_TOKEN_METHODS.has(parsed.method)) {
      err('Failure: no Slack token found. Set SLACK_BOT_TOKEN (xoxb-...) or SLACK_TOKEN (xoxp-...).\n');
      return 2;
    }
    const result = await call(parsed.method, parsed.args, { token, pages: parsed.pages });
    const text = formatResponse(result, { full: parsed.full });
    out(text.endsWith('\n') ? text : text + '\n');
    return 0;
  } catch (e) {
    err('Failure: ' + e.message + '\n');
    return 1;
  }
}

module.exports = { call, parseArgs, runCli, formatResponse, pickToken, SlackApiError, helpText };

if (require.main === module) {
  runCli(process.argv.slice(2)).then((code) => {
    process.exitCode = code;
  });
}

#!/usr/bin/env node
'use strict';

/**
 * Upload a local file to a Slack conversation using the current upload flow:
 *   1. files.getUploadURLExternal   -> upload_url and file_id
 *   2. PUT the raw file bytes to upload_url
 *   3. files.completeUploadExternal -> share the file into a channel
 *
 * Usage:
 *   node upload_file.cjs <file-path> [channel-id] [options]
 *
 * Options:
 *   --comment text    Initial comment shown with the file
 *   --thread-ts TS    Share the file as a reply inside that thread
 *   --title NAME      Display name (defaults to the file's basename)
 *   --alt-text TEXT   Accessibility description
 *   -h, --help        Show this help
 *
 * Environment:
 *   SLACK_BOT_TOKEN    Bot token (xoxb-...). Recommended.
 *   SLACK_TOKEN        User token (xoxp-...) fallback.
 *   SLACK_API_BASE_URL Override API base URL (default https://slack.com/api).
 */

const fs = require('node:fs');
const path = require('node:path');

const DEFAULT_BASE_URL = 'https://slack.com/api';

function pickToken() {
  return (
    process.env.SLACK_BOT_TOKEN ||
    process.env.SLACK_TOKEN ||
    process.env.SLACK_OAUTH_TOKEN ||
    ''
  );
}

function helpText() {
  return [
    'Usage: node upload_file.cjs <file-path> [channel-id] [options]',
    '',
    'Uploads a local file and shares it into a Slack channel using',
    'files.getUploadURLExternal + PUT + files.completeUploadExternal.',
    '',
    'Options:',
    '  --comment text   Initial comment shown with the file',
    '  --thread-ts TS   Share the file inside that thread',
    '  --title NAME     Display name (defaults to the file basename)',
    '  --alt-text TEXT  Accessibility description',
    '  -h, --help       Show this help',
    '',
    'Environment: set SLACK_BOT_TOKEN (xoxb-...) or SLACK_TOKEN (xoxp-...).',
    '',
  ].join('\n');
}

function parseArgs(argv) {
  const out = {
    file: null,
    channel: null,
    comment: null,
    threadTs: null,
    title: null,
    altText: null,
    help: false,
  };
  const positional = [];
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      out.help = true;
    } else if (arg === '--comment') {
      out.comment = argv[++i] || '';
    } else if (arg === '--thread-ts') {
      out.threadTs = argv[++i] || '';
    } else if (arg === '--title') {
      out.title = argv[++i] || '';
    } else if (arg === '--alt-text') {
      out.altText = argv[++i] || '';
    } else if (arg.startsWith('--')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      positional.push(arg);
    }
  }
  out.file = positional[0] || null;
  out.channel = positional[1] || null;
  return out;
}

class SlackApiError extends Error {
  constructor(body) {
    const detail = [];
    if (body.needed) detail.push('needed scope: ' + body.needed);
    if (body.provided) detail.push('provided scopes: ' + body.provided);
    const suffix = detail.length ? ' (' + detail.join('; ') + ')' : '';
    super('Slack API error: ' + (body.error || 'unknown') + suffix);
    this.name = 'SlackApiError';
    this.body = body;
  }
}

async function postJson(baseUrl, method, payload, token) {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers.Authorization = 'Bearer ' + token;
  const res = await fetch(baseUrl + '/' + method, {
    method: 'POST',
    headers,
    body: JSON.stringify(payload),
  });
  let body;
  try {
    body = await res.json();
  } catch (err) {
    throw new Error('HTTP ' + res.status + ' ' + res.statusText + ': response was not JSON');
  }
  if (!body.ok) throw new SlackApiError(body);
  return body;
}

async function runCli(argv, io = {}) {
  const out = io.out || ((s) => process.stdout.write(s));
  const err = io.err || ((s) => process.stderr.write(s));
  let parsed;
  try {
    parsed = parseArgs(argv);
  } catch (e) {
    err('Failure: ' + e.message + '\n');
    return 2;
  }
  if (parsed.help || !parsed.file) {
    out(helpText());
    return parsed.help ? 0 : 2;
  }
  try {
    if (typeof fetch !== 'function') {
      throw new Error('global fetch is unavailable; run with Node.js 18+');
    }
    const token = pickToken();
    if (!token) {
      err('Failure: no Slack token found. Set SLACK_BOT_TOKEN (xoxb-...) or SLACK_TOKEN (xoxp-...).\n');
      return 2;
    }
    const baseUrl = process.env.SLACK_API_BASE_URL || DEFAULT_BASE_URL;
    const filePath = path.resolve(parsed.file);
    if (!fs.existsSync(filePath)) throw new Error('file not found: ' + filePath);
    const stat = fs.statSync(filePath);
    if (!stat.isFile()) throw new Error('not a regular file: ' + filePath);

    const filename = parsed.title || path.basename(filePath);
    const initPayload = { filename, length: stat.size };
    if (parsed.altText) initPayload.alt_txt = parsed.altText;

    const init = await postJson(baseUrl, 'files.getUploadURLExternal', initPayload, token);
    const uploadUrl = init.upload_url;
    const fileId = init.file_id;
    if (!uploadUrl || !fileId) {
      throw new Error('upload response missing upload_url or file_id');
    }

    const data = fs.readFileSync(filePath);
    const putRes = await fetch(uploadUrl, {
      method: 'PUT',
      headers: {
        Authorization: 'Bearer ' + token,
        'Content-Type': 'application/octet-stream',
      },
      body: data,
    });
    if (!putRes.ok) {
      let detail = '';
      try {
        detail = (await putRes.text()).slice(0, 200);
      } catch (ignored) {
        /* no body */
      }
      throw new Error('upload PUT failed with HTTP ' + putRes.status + (detail ? ': ' + detail : ''));
    }

    const completePayload = { files: [{ id: fileId }] };
    if (parsed.channel) completePayload.channel_id = parsed.channel;
    if (parsed.comment) completePayload.initial_comment = parsed.comment;
    if (parsed.threadTs) completePayload.thread_ts = parsed.threadTs;
    const complete = await postJson(baseUrl, 'files.completeUploadExternal', completePayload, token);

    const result = {
      ok: true,
      file: filename,
      file_id: fileId,
      channel: complete.channel || parsed.channel || null,
      ts: complete.ts || (complete.files && complete.files[0] && complete.files[0].ts) || null,
      message: (complete.message && complete.message.text) || null,
    };
    out(JSON.stringify(result, null, 2) + '\n');
    return 0;
  } catch (e) {
    err('Failure: ' + e.message + '\n');
    return 1;
  }
}

module.exports = { parseArgs, runCli, pickToken, SlackApiError, helpText };

if (require.main === module) {
  runCli(process.argv.slice(2)).then((code) => {
    process.exitCode = code;
  });
}

'use strict';

/**
 * Offline tests for the slack-api skill's bundled scripts.
 * Stubs global fetch so no network or Slack token is needed.
 */

const fs = require('node:fs');
const slackMod = require('./slack-api/scripts/slack.cjs');
const uploadMod = require('./slack-api/scripts/upload_file.cjs');

let failures = 0;
function check(name, cond, detail) {
  if (cond) {
    console.log('PASS: ' + name);
  } else {
    failures += 1;
    console.error('FAIL: ' + name + (detail ? ' -- ' + detail : ''));
  }
}

function jsonResponse(status, body) {
  return {
    status,
    statusText: status === 200 ? 'OK' : 'Error',
    ok: status >= 200 && status < 300,
    json: async () => body,
    text: async () => JSON.stringify(body),
    headers: { get: () => null },
  };
}

function textResponse(status, text) {
  return {
    status,
    statusText: status === 200 ? 'OK' : 'Error',
    ok: status >= 200 && status < 300,
    json: async () => {
      throw new Error('no json body');
    },
    text: async () => text,
    headers: { get: () => null },
  };
}

function capture(out, err) {
  return {
    out: (s) => {
      out.push(s);
    },
    err: (s) => {
      err.push(s);
    },
  };
}

async function scenario(name, fn) {
  try {
    await fn();
  } catch (e) {
    failures += 1;
    console.error('FAIL: ' + name + ' threw: ' + e.stack);
  }
}

const TOKEN = 'xoxb-test-token';
const saved = {
  bot: process.env.SLACK_BOT_TOKEN,
  user: process.env.SLACK_TOKEN,
  oauth: process.env.SLACK_OAUTH_TOKEN,
};
function setToken(v) {
  process.env.SLACK_BOT_TOKEN = v;
  process.env.SLACK_TOKEN = v;
  process.env.SLACK_OAUTH_TOKEN = v;
}

async function main() {
  setToken(TOKEN);

  await scenario('api.test without token', async () => {
    setToken(undefined);
    global.fetch = async () => jsonResponse(200, { ok: true });
    const o = [];
    const e = [];
    const code = await slackMod.runCli(['api.test'], capture(o, e));
    check('api.test exit code 0', code === 0, 'code=' + code);
    check('api.test prints ok result', o.join('').includes('"ok": true'), o.join(''));
    check('api.test no stderr', e.join('') === '', e.join(''));
    setToken(TOKEN);
  });

  await scenario('chat.postMessage sends JSON with auth header', async () => {
    const calls = [];
    global.fetch = async (url, init) => {
      calls.push({ url, init });
      return jsonResponse(200, { ok: true, channel: 'C1', ts: '111.1', message: { text: 'hi' } });
    };
    const o = [];
    const e = [];
    const code = await slackMod.runCli(['chat.postMessage', '{"channel":"C1","text":"hi"}'], capture(o, e));
    check('postMessage exit code 0', code === 0, 'code=' + code);
    check('postMessage hit right endpoint', calls[0].url.endsWith('/chat.postMessage'), calls[0] && calls[0].url);
    check('postMessage sends bearer token', calls[0].init.headers.Authorization === 'Bearer ' + TOKEN);
    const sent = JSON.parse(calls[0].init.body);
    check('postMessage body correct', sent.channel === 'C1' && sent.text === 'hi', JSON.stringify(sent));
    check('postMessage prints ts', o.join('').includes('"ts": "111.1"'), o.join(''));
    check('postMessage no stderr', e.join('') === '', e.join(''));
  });

  await scenario('cursor pagination with --pages', async () => {
    const calls = [];
    global.fetch = async (url, init) => {
      const body = JSON.parse(init.body);
      calls.push(body);
      if (!body.cursor) {
        return jsonResponse(200, { ok: true, members: [{ id: 'u1' }, { id: 'u2' }], response_metadata: { next_cursor: 'c1' } });
      }
      if (body.cursor === 'c1') {
        return jsonResponse(200, { ok: true, members: [{ id: 'u3' }, { id: 'u4' }], response_metadata: { next_cursor: 'c2' } });
      }
      return jsonResponse(200, { ok: true, members: [{ id: 'u5' }, { id: 'u6' }] });
    };
    const o = [];
    const e = [];
    const code = await slackMod.runCli(['conversations.list', '{"types":"public_channel"}', '--pages', '3'], capture(o, e));
    check('pagination exit code 0', code === 0, 'code=' + code);
    const parsed = JSON.parse(o.join(''));
    check('pagination merged 6 members', parsed.response.members.length === 6, String(parsed.response && parsed.response.members && parsed.response.members.length));
    check('pagination pagesUsed 3', parsed.pagesUsed === 3, String(parsed.pagesUsed));
    check('pagination sent 3 requests', calls.length === 3, String(calls.length));
    check('pagination cursor forwarded', calls[1].cursor === 'c1' && calls[2].cursor === 'c2', JSON.stringify(calls));
    check('pagination no stderr', e.join('') === '', e.join(''));
  });

  await scenario('ok:false surfaces error and needed scope', async () => {
    global.fetch = async () =>
      jsonResponse(200, { ok: false, error: 'missing_scope', needed: 'channels:history', provided: 'channels:read' });
    const o = [];
    const e = [];
    const code = await slackMod.runCli(['conversations.history', '{"channel":"C1"}'], capture(o, e));
    check('error exit code 1', code === 1, 'code=' + code);
    check('error names the code', e.join('').includes('Slack API error: missing_scope'), e.join(''));
    check('error names the needed scope', e.join('').includes('needed scope: channels:history'), e.join(''));
  });

  await scenario('HTTP 429 mentions retry', async () => {
    global.fetch = async () => ({
      status: 429,
      statusText: 'Too Many Requests',
      ok: false,
      json: async () => {
        throw new Error('no json');
      },
      headers: { get: (k) => (k === 'retry-after' ? '30' : null) },
    });
    const o = [];
    const e = [];
    const code = await slackMod.runCli(['conversations.history', '{"channel":"C1"}'], capture(o, e));
    check('429 exit code 1', code === 1, 'code=' + code);
    check('429 mentions rate limit and retry-after', e.join('').includes('rate limit') && e.join('').includes('30'), e.join(''));
  });

  await scenario('large output is truncated unless --full', async () => {
    const items = [];
    for (let i = 0; i < 500; i += 1) items.push({ id: 'item' + i, text: 'x'.repeat(20) });
    global.fetch = async () => jsonResponse(200, { ok: true, items });
    const o1 = [];
    const code1 = await slackMod.runCli(['big.list', '{}'], capture(o1, []));
    check('truncated run exit code 0', code1 === 0, 'code=' + code1);
    check('default output is truncated with hint', o1.join('').includes('output truncated'), o1.join('').slice(0, 200));
    const o2 = [];
    const code2 = await slackMod.runCli(['big.list', '{}', '--full'], capture(o2, []));
    const full = JSON.parse(o2.join(''));
    check('--full exit code 0', code2 === 0, 'code=' + code2);
    check('--full prints all 500 items', full.response.items.length === 500, String(full.response && full.response.items && full.response.items.length));
  });

  await scenario('tokenless non-api method is rejected before any call', async () => {
    setToken(undefined);
    let fetchCalled = false;
    global.fetch = async () => {
      fetchCalled = true;
      return jsonResponse(200, { ok: true });
    };
    const o = [];
    const e = [];
    const code = await slackMod.runCli(['chat.postMessage', '{}'], capture(o, e));
    check('tokenless rejected with code 2', code === 2, 'code=' + code);
    check('tokenless explains env var', e.join('').includes('SLACK_BOT_TOKEN'), e.join(''));
    check('fetch never called', !fetchCalled);
    setToken(TOKEN);
  });

  await scenario('--help prints usage', async () => {
    const o = [];
    const code = await slackMod.runCli(['--help'], capture(o, []));
    check('help exit code 0', code === 0, 'code=' + code);
    check('help shows usage line', o.join('').includes('Usage: node slack.cjs'), o.join('').slice(0, 120));
  });

  await scenario('upload_file.cjs runs the 3-step flow', async () => {
    const tmpFile = 'upload-tmp.txt';
    const payload = 'hello slack upload bytes';
    fs.writeFileSync(tmpFile, payload, 'utf8');
    const size = Buffer.byteLength(payload);
    let putCapture = null;
    let completeBody = null;
    global.fetch = async (url, init) => {
      if (url.includes('files.getUploadURLExternal')) {
        return jsonResponse(200, { ok: true, upload_url: 'https://files.example.test/up/abc', file_id: 'F900' });
      }
      if (url === 'https://files.example.test/up/abc') {
        putCapture = { url, init };
        return textResponse(200, '');
      }
      if (url.includes('files.completeUploadExternal')) {
        completeBody = JSON.parse(init.body);
        return jsonResponse(200, { ok: true, channel: 'C1', ts: '123.456', files: [{ id: 'F900', ts: '123.456' }], message: { text: 'hi' } });
      }
      throw new Error('unexpected URL: ' + url);
    };
    const o = [];
    const e = [];
    const code = await uploadMod.runCli([tmpFile, 'C1', '--comment', 'hi', '--thread-ts', '111.1'], capture(o, e));
    check('upload exit code 0', code === 0, 'code=' + code);
    check('upload prints file_id and channel', o.join('').includes('F900') && o.join('').includes('"channel": "C1"'), o.join(''));
    check('upload PUT sent with token and full bytes', putCapture && putCapture.init.method === 'PUT' && putCapture.init.body.length === size, JSON.stringify(putCapture && putCapture.init && { method: putCapture.init.method, len: putCapture.init.body && putCapture.init.body.length }));
    check('upload complete payload correct', completeBody && completeBody.files[0].id === 'F900' && completeBody.channel_id === 'C1' && completeBody.initial_comment === 'hi' && completeBody.thread_ts === '111.1', JSON.stringify(completeBody));
    check('upload no stderr', e.join('') === '', e.join(''));
    fs.unlinkSync(tmpFile);
  });

  process.env.SLACK_BOT_TOKEN = saved.bot;
  process.env.SLACK_TOKEN = saved.user;
  process.env.SLACK_OAUTH_TOKEN = saved.oauth;

  console.log(failures === 0 ? '\nALL TESTS PASSED' : '\n' + failures + ' TEST(S) FAILED');
  process.exitCode = failures === 0 ? 0 : 1;
}

main().catch((e) => {
  console.error('Test runner failed: ' + e.stack);
  process.exitCode = 1;
});
